    assert.equal(rows[0].getAttribute('data-outcome-id'), 'seed1');
    assert.equal(rows[0].querySelector('[data-outcome-name]').value, 'Hit');

    // The formula field lives on The roll, the tier rows on Outcomes (issue 1096), so the
