              kind: 'event',
              record: {
                name: 'Disabled Event',
                description: 'Disabled globally.',
                img: 'icons/svg/hazard.svg',
                dropRate: 10,
              },
              compositionState: 'libraryDisabled',
              runtimeState: 'unavailable',
